  monedaState = { moneda: "ARS", tipoCambio: 0 },
  fmt = (n, d) => {
    if (n == null || isNaN(n)) return "—";
    if (monedaState.moneda === "USD") {
      const g = Number(d) || monedaState.tipoCambio;
      if (!g) return "US$ —";
      const C = n < 0,
        S = Math.round(Math.abs(n) / g).toLocaleString("en-US");
      return (C ? "-US$" : "US$") + S;
    }
    const c = n < 0,
      p = Math.round(Math.abs(n)).toLocaleString("de-DE");
    return (c ? "-$" : "$") + p;
  },
  fmt2 = (n, d) => {
    if (n == null || isNaN(n)) return "—";
    if (monedaState.moneda === "USD") {
      const g = Number(d) || monedaState.tipoCambio;
      if (!g) return "US$ —";
      const C = n < 0,
        S = (Math.abs(n) / g).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      return (C ? "-US$" : "US$") + S;
    }
    const c = n < 0,
      p = Math.abs(n).toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return (c ? "-$" : "$") + p;
  },
  pct = (n) => (n == null || isNaN(n) ? "—" : n.toFixed(1) + "%"),
  markupDeMb = (n) => (n == null || isNaN(n) || n >= 100 ? null : (n / (100 - n)) * 100),
  pctMk = (n) => pct(n) + " / " + (markupDeMb(n) == null ? "—" : markupDeMb(n).toFixed(1) + "%");
